import React from 'react';
import { useLocation } from 'react-router-dom';
import Header from './Header';

interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const location = useLocation();
  const isHostFunnelPage = location.pathname === '/host-funnel';
  const isSettlementPage = location.pathname === '/settlement';
  const isAdminSettlementPage = location.pathname === '/admin-settlement';
  const isHostManagementPage = location.pathname === '/host-management';
  const isManualEditPage = location.pathname.includes('/manuals') && (location.pathname.includes('/new') || location.pathname.includes('/edit'));
  const isAnnouncementEditPage = location.pathname.includes('/announcements') && (location.pathname.includes('/new') || location.pathname.includes('/edit'));
  const isWideLayout = isHostFunnelPage || isSettlementPage || isAdminSettlementPage || isHostManagementPage || isManualEditPage || isAnnouncementEditPage;

  return (
    <div className="min-h-screen bg-gray-50">
      <Header />
      <main 
        className={`mx-auto ${isWideLayout ? 'max-w-full px-0 py-0' : 'max-w-4xl px-4 py-6'}`} 
        style={isWideLayout ? { paddingTop: '120px', height: 'calc(100vh - 120px)' } : { paddingTop: '120px' }}
      >
        {children}
      </main>
    </div>
  );
};

export default Layout;
