import React from 'react';
import { SearchResult } from '../../types';
import { highlightSearchTerm } from '../../utils/searchUtils';
import { useClipboard } from '../../hooks/useClipboard';

interface SearchResultItemProps {
  result: SearchResult;
  searchTerm: string;
  onCopySuccess: (text: string) => void;
  onCopyError: (error: string) => void;
}

const SearchResultItem: React.FC<SearchResultItemProps> = ({
  result,
  searchTerm,
  onCopySuccess,
  onCopyError
}) => {
  const { copyText } = useClipboard(onCopySuccess, onCopyError);

  const handleCopyStayName = () => {
    copyText(result.stayName);
  };

  const handleCopyAddress = () => {
    copyText(result.address);
  };

  const handleCopyNote = () => {
    if (result.note) {
      copyText(result.note);
    }
  };

  return (
    <div className="p-4 border-b border-gray-200 hover:bg-gray-50 transition-colors">
      {/* Stay Name */}
      <div 
        onClick={handleCopyStayName}
        className="mb-2 cursor-pointer hover:bg-blue-50 p-2 rounded transition-colors"
        style={{ minHeight: '44px' }}
      >
        <h3 className="font-semibold text-gray-900 text-lg">
          {result.stayName}
        </h3>
      </div>

      {/* Address */}
      <div 
        onClick={handleCopyAddress}
        className={`cursor-pointer hover:bg-blue-50 p-2 rounded transition-colors ${
          result.note ? 'mb-2' : ''
        }`}
        style={{ minHeight: '44px' }}
      >
        <p 
          className="text-gray-700 text-sm"
          dangerouslySetInnerHTML={{ 
            __html: highlightSearchTerm(result.address, searchTerm) 
          }}
        />
      </div>

      {/* Note - 메모가 있을 때만 표시 */}
      {result.note && (
        <div 
          onClick={handleCopyNote}
          className="cursor-pointer hover:bg-blue-50 p-2 rounded transition-colors"
          style={{ minHeight: '44px' }}
        >
          <p className="text-gray-500 text-sm">
            {result.note}
          </p>
        </div>
      )}
    </div>
  );
};

export default SearchResultItem; 