import React from 'react';

interface ManualCategoryDeleteConfirmModalProps {
  isOpen: boolean;
  categoryName: string;
  manualCount: number;
  onConfirm: () => void;
  onCancel: () => void;
  isProcessing?: boolean;
}

const ManualCategoryDeleteConfirmModal: React.FC<ManualCategoryDeleteConfirmModalProps> = ({
  isOpen,
  categoryName,
  manualCount,
  onConfirm,
  onCancel,
  isProcessing = false,
}) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full mx-4">
        <h2 className="text-xl font-bold text-gray-900 mb-4">카테고리 삭제 확인</h2>
        <p className="text-gray-700 mb-4">
          정말로 <strong>"{categoryName}"</strong> 카테고리를 삭제하시겠습니까?
        </p>
        {manualCount > 0 && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-4">
            <p className="text-sm text-red-800">
              ⚠️ 해당 카테고리의 모든 메뉴얼({manualCount}개)도 함께 삭제됩니다.
            </p>
          </div>
        )}
        <p className="text-sm text-gray-600 mb-6">
          이 작업은 되돌릴 수 없습니다.
        </p>
        <div className="flex justify-end gap-3">
          <button
            onClick={onCancel}
            disabled={isProcessing}
            className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            취소
          </button>
          <button
            onClick={onConfirm}
            disabled={isProcessing}
            className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isProcessing ? '삭제 중...' : '삭제'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ManualCategoryDeleteConfirmModal;
