import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { OrderSheetResponse, Order, DateFilter } from '../types';
import { getOrderSheet, getGiftOrderSheet } from '../utils/api';
import { getReservationOrderSheet } from '../utils/reservationApi';
import { isToday, isYesterday, isTodayReservation, isYesterdayReservation } from '../utils/dateUtils';
import { useOrderKey } from '../hooks/useOrderKey';
import OrderCard from '../components/OrderCard';
import OrderSummary from '../components/OrderSummary';
import FilterToggle from '../components/FilterToggle';
import StatusFilter from '../components/StatusFilter';
import OrderTypeTab, { OrderType } from '../components/OrderTypeTab';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';

const OrdersPage: React.FC = () => {
  const [orderData, setOrderData] = useState<OrderSheetResponse | null>(null);
  const [giftOrderData, setGiftOrderData] = useState<OrderSheetResponse | null>(null);
  const [reservationOrderData, setReservationOrderData] = useState<OrderSheetResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<OrderType>('food');
  const [dateFilter, setDateFilter] = useState<DateFilter>(DateFilter.TODAY); // 기본값: 오늘 주문만 표시
  const [showPreparedOrders, setShowPreparedOrders] = useState(false); // 기본값: PREPARED 상태 숨김
  
  // 카운트 캐시 (탭별 today/yesterday/total 카운트 저장)
  const [countCache, setCountCache] = useState<{
    food: { today: number | null, yesterday: number | null, total: number | null },
    gift: { today: number | null, yesterday: number | null, total: number | null },
    reservation: { today: number | null, yesterday: number | null, total: number | null }
  }>({
    food: { today: null, yesterday: null, total: null },
    gift: { today: null, yesterday: null, total: null },
    reservation: { today: null, yesterday: null, total: null }
  });

  const { key } = useOrderKey();

  // API 호출
  const fetchOrderData = useCallback(async (apiKey: string) => {
    try {
      setLoading(true);
      setError(null);
      
      // 음식배달, 기프트샵, 예약배달 데이터를 병렬로 가져오기
      const [foodData, giftData, reservationData] = await Promise.all([
        getOrderSheet(apiKey, dateFilter),
        getGiftOrderSheet(apiKey, dateFilter),
        getReservationOrderSheet(apiKey, dateFilter)
      ]);
      
      setOrderData(foodData);
      setGiftOrderData(giftData);
      setReservationOrderData(reservationData);
      
      // 카운트 캐시 업데이트
      const updateCountCache = (tabName: 'food' | 'gift' | 'reservation', data: OrderSheetResponse) => {
        if (dateFilter === DateFilter.TODAY) {
          // 오늘만 조회한 경우: 오늘 카운트만 업데이트
          const todayCount = data.orders.length;
          setCountCache(prev => ({
            ...prev,
            [tabName]: { ...prev[tabName], today: todayCount }
          }));
        } else if (dateFilter === DateFilter.YESTERDAY) {
          // 어제만 조회한 경우: 어제 카운트만 업데이트
          const yesterdayCount = data.orders.length;
          setCountCache(prev => ({
            ...prev,
            [tabName]: { ...prev[tabName], yesterday: yesterdayCount }
          }));
        } else {
          // 전체 조회한 경우: 전체 카운트, 오늘 카운트, 어제 카운트 모두 업데이트
          const totalCount = data.orders.length;
          const todayCount = data.orders.filter(order => {
            return tabName === 'reservation' 
              ? (order.reservationDateTime ? isTodayReservation(order.reservationDateTime) : false)
              : isToday(order.createdDate);
          }).length;
          const yesterdayCount = data.orders.filter(order => {
            return tabName === 'reservation' 
              ? (order.reservationDateTime ? isYesterdayReservation(order.reservationDateTime) : false)
              : isYesterday(order.createdDate);
          }).length;
          
          setCountCache(prev => ({
            ...prev,
            [tabName]: { today: todayCount, yesterday: yesterdayCount, total: totalCount }
          }));
        }
      };
      
      updateCountCache('food', foodData);
      updateCountCache('gift', giftData);
      updateCountCache('reservation', reservationData);
    } catch (err) {
      setError(err instanceof Error ? err.message : '주문서 정보를 불러오는데 실패했습니다.');
    } finally {
      setLoading(false);
    }
  }, [dateFilter]);

  // key가 있을 때 API 호출
  useEffect(() => {
    if (key) {
      fetchOrderData(key);
    } else {
      setLoading(false);
      setError('올바른 접근 키가 필요합니다. URL에 key 파라미터를 포함해주세요.');
    }
  }, [key, fetchOrderData]);

  // 필터링된 주문 목록 계산
  const { filteredOrders, todayOrdersCount, yesterdayOrdersCount, totalOrdersCount, currentPaidCount, currentPreparedCount } = useMemo(() => {
    // 현재 활성 탭에 따라 데이터 선택
    const currentOrderData = activeTab === 'food' ? orderData : 
                             activeTab === 'gift' ? giftOrderData : 
                             reservationOrderData;
    
    if (!currentOrderData?.orders) {
      // 데이터가 없어도 캐시된 카운트는 사용
      const currentTabCache = countCache[activeTab];
      return { 
        filteredOrders: [], 
        todayOrdersCount: currentTabCache.today,
        yesterdayOrdersCount: currentTabCache.yesterday,
        totalOrdersCount: currentTabCache.total,
        currentPaidCount: 0,
        currentPreparedCount: 0
      };
    }

    // 1단계: 날짜별 필터링
    const dateFilteredOrders = dateFilter === DateFilter.ALL
      ? currentOrderData.orders
      : currentOrderData.orders.filter(order => {
          // 예약배달은 예약시간 기준, 나머지는 생성시간 기준
          if (activeTab === 'reservation') {
            if (!order.reservationDateTime) return false;
            return dateFilter === DateFilter.TODAY 
              ? isTodayReservation(order.reservationDateTime)
              : isYesterdayReservation(order.reservationDateTime);
          } else {
            return dateFilter === DateFilter.TODAY 
              ? isToday(order.createdDate)
              : isYesterday(order.createdDate);
          }
        });

    // 2단계: 언어별 필터링 (KO 제외)
    const languageFilteredOrders = dateFilteredOrders;

    // 3단계: 상태별 필터링
    const finalOrders = showPreparedOrders 
      ? languageFilteredOrders // 모든 상태 포함
      : languageFilteredOrders.filter(order => order.status !== 'PREPARED'); // PREPARED 제외

    // 현재 날짜 필터 + 언어 필터 기준 상태별 통계
    const currentPaidOrders = languageFilteredOrders.filter(order => order.status !== 'PREPARED');
    const currentPreparedOrders = languageFilteredOrders.filter(order => order.status === 'PREPARED');

    // 캐시된 카운트 사용
    const currentTabCache = countCache[activeTab];
    const cachedTodayCount = currentTabCache.today;
    const cachedYesterdayCount = currentTabCache.yesterday;
    const cachedTotalCount = currentTabCache.total;

    return {
      filteredOrders: finalOrders,
      todayOrdersCount: cachedTodayCount,
      yesterdayOrdersCount: cachedYesterdayCount,
      totalOrdersCount: cachedTotalCount,
      currentPaidCount: currentPaidOrders.length,
      currentPreparedCount: currentPreparedOrders.length
    };
  }, [activeTab, orderData, giftOrderData, reservationOrderData, dateFilter, showPreparedOrders, countCache]);

  const handleRetry = () => {
    if (key) {
      fetchOrderData(key);
    }
  };

  const handleFilterToggle = (filter: DateFilter) => {
    setDateFilter(filter);
  };

  const handleStatusFilterToggle = (showPrepared: boolean) => {
    setShowPreparedOrders(showPrepared);
  };

  const handleTabChange = (tab: OrderType) => {
    setActiveTab(tab);
  };

  // 주문 업데이트 콜백 함수
  const handleOrderUpdate = (orderId: string, updatedOrder: Order) => {
    if (activeTab === 'food' && orderData) {
      setOrderData({
        ...orderData,
        orders: orderData.orders.map(order => 
          order.orderId === orderId ? updatedOrder : order
        )
      });
    } else if (activeTab === 'gift' && giftOrderData) {
      setGiftOrderData({
        ...giftOrderData,
        orders: giftOrderData.orders.map(order => 
          order.orderId === orderId ? updatedOrder : order
        )
      });
    } else if (activeTab === 'reservation' && reservationOrderData) {
      setReservationOrderData({
        ...reservationOrderData,
        orders: reservationOrderData.orders.map(order => 
          order.orderId === orderId ? updatedOrder : order
        )
      });
    }
  };

  return (
    <>
      {loading && <LoadingSpinner />}
      
      {error && (
        <ErrorMessage 
          message={error} 
          onRetry={key ? handleRetry : undefined}
        />
      )}
      
      {(orderData || giftOrderData || reservationOrderData) && (
        <>
          {/* 주문 타입 탭 */}
          <OrderTypeTab
            activeTab={activeTab}
            onTabChange={handleTabChange}
          />

          {/* 필터 토글 */}
          <FilterToggle
            dateFilter={dateFilter}
            onToggle={handleFilterToggle}
            todayCount={todayOrdersCount}
            yesterdayCount={yesterdayOrdersCount}
            totalCount={totalOrdersCount}
          />

          {/* 상태 필터 */}
          <StatusFilter
            showPreparedOrders={showPreparedOrders}
            onToggle={handleStatusFilterToggle}
            paidCount={currentPaidCount}
            preparedCount={currentPreparedCount}
          />

          {filteredOrders.length > 0 ? (
            <>
              <OrderSummary orders={filteredOrders} />
              
              <div className="space-y-4">
                <h2 className="text-lg font-semibold text-gray-900">
                  {activeTab === 'food' ? '🍕 바로배달' : 
                   activeTab === 'reservation' ? '⏰ 예약배달' : '🎁 기프트샵'} - {
                    dateFilter === DateFilter.TODAY ? '오늘 주문 상세' :
                    dateFilter === DateFilter.YESTERDAY ? '어제 주문 상세' :
                    '전체 주문 상세'
                  }
                </h2>
                {filteredOrders.map((order) => (
                  <OrderCard 
                    key={order.orderId} 
                    order={order} 
                    orderType={activeTab}
                    onOrderUpdate={handleOrderUpdate}
                  />
                ))}
              </div>
            </>
          ) : (
            <div className="bg-white rounded-lg shadow-sm p-8 text-center">
              <p className="text-gray-600">
                {dateFilter === DateFilter.TODAY ? '오늘 등록된 주문이 없습니다.' :
                 dateFilter === DateFilter.YESTERDAY ? '어제 등록된 주문이 없습니다.' :
                 '등록된 주문이 없습니다.'}
              </p>
            </div>
          )}
        </>
      )}
    </>
  );
};

export default OrdersPage;
