import { Stay, SearchResult } from '../types';

// 검색어로 stays를 필터링하는 함수
export const searchStays = (stays: Stay[], searchTerm: string): SearchResult[] => {
  // 2글자 미만이면 빈 배열 반환
  if (searchTerm.length < 2) {
    return [];
  }

  const lowerSearchTerm = searchTerm.toLowerCase();

  return stays
    .filter(stay => 
      stay.address.address.toLowerCase().includes(lowerSearchTerm)
    )
    .map(stay => ({
      id: stay.id,
      stayName: stay.stay_name,
      address: stay.address.address,
      note: stay.note
    }));
};

// 텍스트에서 검색어 부분을 하이라이트하는 함수
export const highlightSearchTerm = (text: string, searchTerm: string): string => {
  if (!searchTerm || searchTerm.length < 2) {
    return text;
  }

  const regex = new RegExp(`(${escapeRegExp(searchTerm)})`, 'gi');
  return text.replace(regex, '<mark class="bg-yellow-200">$1</mark>');
};

// 정규식 특수문자 이스케이프
const escapeRegExp = (string: string): string => {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
};

// 디바운스 함수
export const debounce = <T extends (...args: any[]) => void>(
  func: T,
  delay: number
): ((...args: Parameters<T>) => void) => {
  let timeoutId: NodeJS.Timeout;
  
  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func(...args), delay);
  };
}; 