import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  getManualDetail,
  createManual,
  updateManual,
} from '../utils/manualApi';
import { getManualCategoryList } from '../utils/manualCategoryApi';
import { ManualCategory } from '../types';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import MarkdownEditor from '../components/MarkdownEditor';
import MarkdownViewer from '../components/MarkdownViewer';

const ManualEditPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { showToast } = useToast();

  const mode = id ? 'edit' : 'create';

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [sortOrder, setSortOrder] = useState<number | undefined>(undefined);
  const [categories, setCategories] = useState<ManualCategory[]>([]);
  const [errors, setErrors] = useState<{ title?: string; content?: string; categoryId?: string }>({});
  const [loading, setLoading] = useState(mode === 'edit');
  const [error, setError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [mobileView, setMobileView] = useState<'editor' | 'preview'>('editor');

  // 초기 데이터 (수정 모드)
  const [initialData, setInitialData] = useState<{
    title: string;
    content: string;
    categoryId: string;
    sortOrder?: number;
  } | null>(null);

  // 카테고리 목록 조회
  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await getManualCategoryList();
        if (response.success) {
          const sortedCategories = response.data
            .filter((cat) => cat.isActive)
            .sort((a, b) => a.sortOrder - b.sortOrder);
          setCategories(sortedCategories);
          
          // 생성 모드이고 카테고리가 있으면 첫 번째 카테고리 선택
          if (mode === 'create' && sortedCategories.length > 0 && !categoryId) {
            setCategoryId(sortedCategories[0].id);
          }
        }
      } catch (err) {
        console.error('카테고리 목록 조회 실패:', err);
      }
    };
    fetchCategories();
  }, [mode, categoryId]);

  // 수정 모드: 기존 데이터 로드
  useEffect(() => {
    if (mode === 'edit' && id) {
      const fetchManual = async () => {
        try {
          setLoading(true);
          setError(null);
          const response = await getManualDetail(id);
          if (response.success) {
            const data = response.data;
            setTitle(data.title);
            setContent(data.content);
            setCategoryId(data.categoryId);
            setSortOrder(data.sortOrder);
            setInitialData({
              title: data.title,
              content: data.content,
              categoryId: data.categoryId,
              sortOrder: data.sortOrder,
            });
          }
        } catch (err) {
          setError(err instanceof Error ? err.message : '메뉴얼을 불러오는데 실패했습니다.');
        } finally {
          setLoading(false);
        }
      };
      fetchManual();
    }
  }, [mode, id]);

  // 변경사항 감지
  useEffect(() => {
    if (initialData) {
      const changed =
        title !== initialData.title ||
        content !== initialData.content ||
        categoryId !== initialData.categoryId ||
        sortOrder !== initialData.sortOrder;
      setHasChanges(changed);
    } else if (mode === 'create') {
      const changed = title.trim() !== '' || content.trim() !== '';
      setHasChanges(changed);
    }
  }, [title, content, categoryId, sortOrder, initialData, mode]);

  // 유효성 검사
  const validate = (): boolean => {
    const newErrors: { title?: string; content?: string; categoryId?: string } = {};

    if (!title.trim()) {
      newErrors.title = '제목을 입력해주세요.';
    }

    if (!content.trim()) {
      newErrors.content = '내용을 입력해주세요.';
    }

    if (!categoryId) {
      newErrors.categoryId = '카테고리를 선택해주세요.';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // 저장 핸들러
  const handleSubmit = async () => {
    if (!validate()) {
      return;
    }

    setIsSubmitting(true);
    try {
      if (mode === 'create') {
        const response = await createManual({
          title: title.trim(),
          content: content.trim(),
          categoryId,
          sortOrder: sortOrder !== undefined ? sortOrder : undefined,
        });
        if (response.success) {
          showToast('메뉴얼이 성공적으로 생성되었습니다.', 'success');
          navigate('/manuals');
        }
      } else {
        if (!id) return;
        const response = await updateManual(id, {
          title: title.trim(),
          content: content.trim(),
          categoryId,
          sortOrder: sortOrder !== undefined ? sortOrder : undefined,
        });
        if (response.success) {
          showToast('메뉴얼이 성공적으로 수정되었습니다.', 'success');
          navigate(`/manuals/${id}`);
        }
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : `메뉴얼 ${mode === 'create' ? '생성' : '수정'}에 실패했습니다.`,
        'error'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  // 뒤로가기 핸들러
  const handleBack = () => {
    if (hasChanges) {
      if (window.confirm('변경사항이 있습니다. 정말 나가시겠습니까?')) {
        if (mode === 'edit' && id) {
          navigate(`/manuals/${id}`);
        } else {
          navigate('/manuals');
        }
      }
    } else {
      if (mode === 'edit' && id) {
        navigate(`/manuals/${id}`);
      } else {
        navigate('/manuals');
      }
    }
  };

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto">
        <LoadingSpinner />
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto">
        <ErrorMessage message={error} onRetry={() => navigate('/manuals')} />
      </div>
    );
  }

  return (
    <div className="w-full h-full flex flex-col">
      {/* 헤더 */}
      <div className="flex-shrink-0 px-6 py-4 border-b border-gray-200 bg-white flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={handleBack}
            className="text-gray-600 hover:text-gray-900 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <h1 className="text-2xl font-bold text-gray-900">
            {mode === 'create' ? '메뉴얼 작성' : '메뉴얼 수정'}
          </h1>
        </div>
        <div className="flex gap-2">
          <button
            onClick={handleBack}
            disabled={isSubmitting}
            className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50"
          >
            취소
          </button>
          <button
            onClick={handleSubmit}
            disabled={isSubmitting}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
          >
            {isSubmitting ? '저장 중...' : '저장'}
          </button>
        </div>
      </div>

      {/* 폼 */}
      <div className="flex-1 overflow-hidden flex flex-col">
        <div className="flex-1 overflow-y-auto px-6 py-6">
          <div className="space-y-6 max-w-7xl mx-auto">
        {/* 제목 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            제목 <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            disabled={isSubmitting}
            className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
              errors.title ? 'border-red-500' : 'border-gray-300'
            } disabled:bg-gray-100 disabled:cursor-not-allowed`}
            placeholder="메뉴얼 제목을 입력하세요"
          />
          {errors.title && (
            <p className="mt-1 text-sm text-red-500">{errors.title}</p>
          )}
        </div>

        {/* 카테고리 선택 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            카테고리 <span className="text-red-500">*</span>
          </label>
          <select
            value={categoryId}
            onChange={(e) => setCategoryId(e.target.value)}
            disabled={isSubmitting}
            className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
              errors.categoryId ? 'border-red-500' : 'border-gray-300'
            } disabled:bg-gray-100 disabled:cursor-not-allowed`}
          >
            <option value="">카테고리를 선택하세요</option>
            {categories.map((category) => (
              <option key={category.id} value={category.id}>
                {category.name}
              </option>
            ))}
          </select>
          {errors.categoryId && (
            <p className="mt-1 text-sm text-red-500">{errors.categoryId}</p>
          )}
        </div>

        {/* 순서 입력 (선택적) */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            순서 (선택)
          </label>
          <input
            type="number"
            value={sortOrder !== undefined ? sortOrder : ''}
            onChange={(e) => {
              const value = e.target.value;
              setSortOrder(value === '' ? undefined : parseInt(value, 10));
            }}
            disabled={isSubmitting}
            min="1"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-gray-100 disabled:cursor-not-allowed"
            placeholder="순서를 입력하세요 (미입력 시 자동 배치)"
          />
          <p className="mt-1 text-xs text-gray-500">
            순서를 지정하지 않으면 해당 카테고리의 마지막 순서로 자동 배치됩니다.
          </p>
        </div>

        {/* 내용: 분할 뷰 (데스크톱) */}
        <div className="flex-1 flex flex-col min-h-0">
          <label className="block text-sm font-medium text-gray-700 mb-2 flex-shrink-0">
            내용 <span className="text-red-500">*</span>
          </label>
          
          {/* 데스크톱: 분할 뷰 */}
          <div className="hidden lg:grid lg:grid-cols-2 lg:gap-4 flex-1 min-h-0">
            {/* 에디터 */}
            <div className="flex flex-col min-h-0">
              <div className="mb-2 text-xs text-gray-500 flex-shrink-0">에디터</div>
              <div className="flex-1 min-h-0">
                <MarkdownEditor
                  value={content}
                  onChange={(value) => setContent(value || '')}
                  disabled={isSubmitting}
                  error={!!errors.content}
                  placeholder="Markdown 형식으로 작성하세요. 이미지를 드래그 앤 드롭하여 업로드할 수 있습니다..."
                />
              </div>
              {errors.content && (
                <p className="mt-1 text-sm text-red-500 flex-shrink-0">{errors.content}</p>
              )}
            </div>

            {/* 미리보기 */}
            <div className="flex flex-col min-h-0">
              <div className="mb-2 text-xs text-gray-500 flex-shrink-0">미리보기</div>
              <div className="border border-gray-300 rounded-lg p-4 bg-white overflow-y-auto flex-1 min-h-0">
                {content.trim() ? (
                  <MarkdownViewer content={content} />
                ) : (
                  <p className="text-gray-400 text-sm">내용을 입력하면 미리보기가 표시됩니다.</p>
                )}
              </div>
            </div>
          </div>

          {/* 모바일/태블릿: 탭 전환 */}
          <div className="lg:hidden">
            <div className="flex border-b border-gray-300 mb-4">
              <button
                type="button"
                onClick={() => setMobileView('editor')}
                className={`flex-1 px-4 py-2 text-sm font-medium text-center border-b-2 transition-colors ${
                  mobileView === 'editor'
                    ? 'border-blue-600 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700'
                }`}
              >
                에디터
              </button>
              <button
                type="button"
                onClick={() => setMobileView('preview')}
                className={`flex-1 px-4 py-2 text-sm font-medium text-center border-b-2 transition-colors ${
                  mobileView === 'preview'
                    ? 'border-blue-600 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700'
                }`}
              >
                미리보기
              </button>
            </div>
            {mobileView === 'editor' ? (
              <>
                <MarkdownEditor
                  value={content}
                  onChange={(value) => setContent(value || '')}
                  disabled={isSubmitting}
                  error={!!errors.content}
                  placeholder="Markdown 형식으로 작성하세요. 이미지를 드래그 앤 드롭하여 업로드할 수 있습니다..."
                />
                {errors.content && (
                  <p className="mt-1 text-sm text-red-500">{errors.content}</p>
                )}
              </>
            ) : (
              <div className="border border-gray-300 rounded-lg p-4 min-h-[400px] bg-white">
                {content.trim() ? (
                  <MarkdownViewer content={content} />
                ) : (
                  <p className="text-gray-400 text-sm">내용을 입력하면 미리보기가 표시됩니다.</p>
                )}
              </div>
            )}
          </div>
          </div>
        </div>
        </div>
      </div>
    </div>
  );
};

export default ManualEditPage;
