import React from 'react';
import GoogleMapComponent from './GoogleMapComponent';
import NaverMapComponent from './NaverMapComponent';

interface MapComparisonProps {
  koreanAddress: string;
  englishAddress: string;
  lat: number;
  lng: number;
  onConfirm: () => void;
  onLocationDifferent?: () => void;
  isLoading?: boolean;
}

const MapComparison: React.FC<MapComparisonProps> = ({
  koreanAddress,
  englishAddress,
  lat,
  lng,
  onConfirm,
  onLocationDifferent,
  isLoading = false
}) => {
  return (
    <div className="space-y-6">
      {/* 안내 메시지 */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex">
          <div className="flex-shrink-0">
            <svg className="h-5 w-5 text-blue-400" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
            </svg>
          </div>
          <div className="ml-3">
            <p className="text-sm text-blue-700">
              두 지도에서 동일한 위치를 가리키는지 확인해주세요. 위치가 정확하면 아래 버튼을 눌러주세요.
            </p>
          </div>
        </div>
      </div>

      {/* 지도 비교 영역 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* 네이버 지도 */}
        <div className="bg-white rounded-lg border border-gray-200 p-4">
          <NaverMapComponent 
            address={koreanAddress}
            lat={lat}
            lng={lng}
          />
        </div>

        {/* 구글 지도 */}
        <div className="bg-white rounded-lg border border-gray-200 p-4">
          <GoogleMapComponent 
            address={englishAddress}
            lat={lat}
            lng={lng}
          />
        </div>
      </div>

      {/* 확인 버튼들 */}
      <div className="flex gap-4 justify-center">
        <button
          onClick={onConfirm}
          disabled={isLoading}
          className={`px-8 py-3 rounded-lg text-white font-medium transition-colors duration-200 ${
            isLoading
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-green-500 hover:bg-green-600'
          }`}
        >
          {isLoading ? (
            <div className="flex items-center">
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Stay 생성 중...
            </div>
          ) : (
            '✅ 위치가 같습니다'
          )}
        </button>
        
        {onLocationDifferent && (
          <button
            onClick={onLocationDifferent}
            disabled={isLoading}
            className={`px-8 py-3 rounded-lg border border-orange-500 text-orange-600 font-medium transition-colors duration-200 ${
              isLoading
                ? 'bg-gray-100 cursor-not-allowed'
                : 'bg-white hover:bg-orange-50'
            }`}
          >
            🔄 위치가 다릅니다
          </button>
        )}
      </div>
    </div>
  );
};

export default MapComparison;
