import React, { useState } from 'react';
import { Order, BROKERS, getBrokerName } from '../types';
import { formatDate, formatTime } from '../utils/dateUtils';
import { updateOrderBroker } from '../utils/brokerApi';
import { useToast } from '../hooks/useToast';
import EmailTemplate from './EmailTemplate';
import SettlementPriceEditor from './SettlementPriceEditor';
import OrderMemoEditor from './OrderMemoEditor';
import StaySearchModal from './StaySearchModal';

interface OrderCardProps {
  order: Order;
  orderType?: 'food' | 'gift' | 'reservation';
  onOrderUpdate?: (orderId: string, updatedOrder: Order) => void;
}

const getLanguageDisplay = (languageCode: string) => {
  switch (languageCode) {
    case 'KO':
      return '한국어';
    case 'EN':
      return 'English';
    case 'JA':
      return '日本語';
    case 'ZH':
      return '中文';
    default:
      return languageCode;
  }
};


const OrderCard: React.FC<OrderCardProps> = ({ order, orderType = 'food', onOrderUpdate }) => {
  const [showCopyToast, setShowCopyToast] = useState(false);
  const [isUpdatingBroker, setIsUpdatingBroker] = useState(false);
  const [currentOrder, setCurrentOrder] = useState<Order>(order);
  const [isStaySearchModalOpen, setIsStaySearchModalOpen] = useState(false);
  
  const { showToast } = useToast();

  // 클립보드 복사 함수
  const copyToClipboard = async (text: string, label: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setShowCopyToast(true);
      setTimeout(() => setShowCopyToast(false), 2000);
    } catch (err) {
      // 복사 실패 시 fallback
      const textArea = document.createElement('textarea');
      textArea.value = text;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      setShowCopyToast(true);
      setTimeout(() => setShowCopyToast(false), 2000);
    }
  };

  // 브로커 할당 함수
  const handleBrokerAssign = async (brokerId: string) => {
    try {
      setIsUpdatingBroker(true);
      await updateOrderBroker(currentOrder.orderId, brokerId);
      
      // 성공 시 로컬 상태 업데이트
      const updatedOrder = {
        ...currentOrder,
        status: 'BROKER_ACCEPTED' as const,
        brokerId: brokerId
      };
      setCurrentOrder(updatedOrder);
      
      // 부모 컴포넌트에 변경사항 알림
      onOrderUpdate?.(currentOrder.orderId, updatedOrder);
      
      showToast(`${getBrokerName(brokerId)}님에게 할당되었습니다.`, 'success');
    } catch (error) {
      // 실패 시 팝업 표시 후 새로고침
      alert('다른 사람에게 할당되었습니다.');
      window.location.reload();
    } finally {
      setIsUpdatingBroker(false);
    }
  };

  // 정산 금액 업데이트 핸들러
  const handleSettlementPriceUpdate = (orderId: string, updatedOrder: Order) => {
    setCurrentOrder(updatedOrder);
    onOrderUpdate?.(orderId, updatedOrder);
  };

  // 메모 업데이트 핸들러
  const handleMemoUpdate = (orderId: string, updatedOrder: Order) => {
    setCurrentOrder(updatedOrder);
    onOrderUpdate?.(orderId, updatedOrder);
  };

  // 총 금액 계산
  const totalAmount = currentOrder.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  
  // 상태 한글 변환
  const getStatusText = (status: string, brokerId?: string) => {
    switch (status) {
      case 'PREPARED': return '장바구니';
      case 'PAID': return '결제완료';
      case 'COOKING': return '조리중';
      case 'DELIVERED': return '배달완료';
      case 'BROKER_ACCEPTED': return brokerId ? `${getBrokerName(brokerId)} 할당` : '브로커 할당';
      case 'RESERVATION_PAID': return '예약';
      default: return status;
    }
  };
  
  // 상태별 색상
  const getStatusColor = (status: string, brokerId?: string) => {
    switch (status) {
      case 'PREPARED': return 'bg-orange-100 text-orange-800 border-orange-200';
      case 'PAID': return 'bg-green-100 text-green-800 border-green-200';
      case 'COOKING': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'DELIVERED': return 'bg-blue-100 text-blue-800 border-blue-200';
      case 'RESERVATION_PAID': return 'bg-teal-100 text-teal-800 border-teal-200';
      case 'BROKER_ACCEPTED': 
        // 브로커별 색상 구분
        switch (brokerId) {
          case 'dongjin.lee': return 'bg-purple-100 text-purple-800 border-purple-200';
          case 'donggyu.lee': return 'bg-indigo-100 text-indigo-800 border-indigo-200';
          case 'wslee': return 'bg-pink-100 text-pink-800 border-pink-200';
          default: return 'bg-gray-100 text-gray-800 border-gray-200';
        }
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6 hover:shadow-md transition-shadow duration-200 relative">
      {/* 복사 완료 토스트 */}
      {showCopyToast && (
        <div className="absolute top-4 right-4 bg-green-500 text-white px-3 py-2 rounded-lg text-sm font-medium z-10 animate-fade-in-out">
          복사완료!
        </div>
      )}

      {/* 1순위: 상태 + 언어 배지 */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-2">
          <span className={`inline-flex items-center px-3 py-1.5 rounded-full text-sm font-medium border ${getStatusColor(currentOrder.status, currentOrder.brokerId)}`}>
            {getStatusText(currentOrder.status, currentOrder.brokerId)}
          </span>
          {/* 예약배달일 때 예약시간 표시 */}
          {orderType === 'reservation' && (
            <span className="inline-flex items-center px-2 py-1 bg-gray-100 text-gray-700 text-xs font-medium rounded border">
              예약시간: {currentOrder.reservationDateTime ? formatTime(currentOrder.reservationDateTime) : '확인 필요'}
            </span>
          )}
          {/* PAID 또는 RESERVATION_PAID 상태이고 브로커가 할당되지 않았을 때만 셀렉트박스 표시 */}
          {(currentOrder.status === 'PAID' || currentOrder.status === 'RESERVATION_PAID') && !currentOrder.brokerId && (
            <select
              className="px-2 py-1 bg-white border border-gray-300 rounded-md text-sm"
              value=""
              onChange={(e) => handleBrokerAssign(e.target.value)}
              disabled={isUpdatingBroker}
            >
              <option value="">담당자 선택</option>
              {BROKERS.map((broker) => (
                <option key={broker.id} value={broker.id}>
                  {broker.name}
                </option>
              ))}
            </select>
          )}
        </div>
        <span className="inline-flex items-center px-3 py-1.5 bg-gray-50 text-gray-700 text-sm font-medium rounded-full border border-gray-200">
          {getLanguageDisplay(currentOrder.languageCode)}
        </span>
      </div>

      {/* 2순위: 레스토랑명 + 총금액 (가장 중요한 정보) */}
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1 mr-4">
          <h2 
            className="text-xl font-semibold text-gray-900 mb-1 cursor-pointer hover:text-blue-600 transition-colors duration-200 select-none"
            onClick={() => copyToClipboard(currentOrder.franchiseStoreName || currentOrder.restaurantName, '가게 이름')}
            title="클릭하여 복사"
          >
            {currentOrder.franchiseStoreName || currentOrder.restaurantName}
          </h2>
          <div className="flex items-center gap-2 mb-1">
            <p 
              className="text-gray-600 flex items-center flex-1 cursor-pointer hover:text-blue-600 transition-colors duration-200 select-none"
              onClick={() => copyToClipboard(currentOrder.stayName || currentOrder.deliveryAddress || '배송지 미등록', '배송지')}
              title="클릭하여 복사"
            >
              <span className="mr-1">📍</span>
              {currentOrder.stayName || currentOrder.deliveryAddress || '배송지 미등록'}
            </p>
            {!currentOrder.stayName && currentOrder.deliveryAddress && (
              <button
                onClick={() => setIsStaySearchModalOpen(true)}
                className="flex-shrink-0 px-2 py-1 text-xs font-medium text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-md transition-colors duration-200"
                title="Stay 연동"
              >
                🔗 연동
              </button>
            )}
          </div>
          {currentOrder.note && (
            <p 
              className="text-gray-600 flex items-center mb-1 cursor-pointer hover:text-blue-600 transition-colors duration-200 select-none"
              onClick={() => copyToClipboard(currentOrder.note!, '메모')}
              title="클릭하여 복사"
            >
              <span className="mr-1">📝</span>
              {currentOrder.note}
            </p>
          )}
        </div>
        <div className="text-right">
          <div className="text-2xl font-bold text-gray-900">
            {totalAmount.toLocaleString()}원
          </div>
          <div className="text-sm text-gray-500">총 주문금액</div>
        </div>
      </div>

      {/* 3순위: 메뉴 상세 */}
      <div className="border-t border-gray-100 pt-4 mb-4">
        <div className="space-y-4">
          {currentOrder.items.map((item, index) => (
            <div key={`${item.menuId}-${index}`} className="bg-gray-50 rounded-lg p-4">
              <div className="flex justify-between items-start mb-3">
                <div className="flex-1 mr-4">
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-medium text-gray-900">
                      {orderType === 'gift' 
                        ? item.name 
                        : (item.franchiseMenuName ? `${item.franchiseMenuName} (${item.name})` : item.name)
                      }
                    </h4>
                    {/* 기프트샵일 때 각 아이템별 쇼핑몰 링크 버튼 */}
                    {orderType === 'gift' && item.shopUrl && (
                      <button
                        onClick={() => window.open(item.shopUrl, '_blank')}
                        className="inline-flex items-center px-2 py-1 bg-blue-600 text-white text-xs font-medium rounded hover:bg-blue-700 transition-colors duration-200"
                        title="쇼핑몰에서 보기"
                      >
                        🛒 쇼핑몰
                      </button>
                    )}
                  </div>
                  <p className="text-sm text-gray-600">수량: {item.quantity}개</p>
                </div>
                <div className="text-right">
                  <p className="font-semibold text-gray-900">
                    {(item.price * item.quantity).toLocaleString()}원
                  </p>
                  <p className="text-xs text-gray-500">
                    개당 {item.price.toLocaleString()}원
                  </p>
                </div>
              </div>
              
              {/* 옵션 상세 정보 - 음식배달일 때만 표시 */}
              {orderType === 'food' && item.options.length > 0 && 
               item.options.some(option => option.optionName.trim() && option.optionItems.some(item => item.trim())) && (
                <div className="border-t border-gray-200 pt-3 space-y-2">
                  {item.options.map((option, optionIndex) => (
                    option.optionName.trim() && option.optionItems.some(item => item.trim()) && (
                      <div key={optionIndex} className="text-sm">
                        <span className="font-medium text-gray-700">{option.optionName}:</span>
                        <span className="ml-2 text-gray-600">
                          {option.optionItems.filter(item => item.trim()).join(', ')}
                        </span>
                      </div>
                    )
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 4순위: 메타 정보 (참조용) */}
      <div className="border-t border-gray-100 pt-4">
        <div className="flex justify-between items-center text-sm text-gray-500">
          <span>DEE 주문번호: {currentOrder.orderId}</span>
          <span>{formatDate(currentOrder.createdDate)}</span>
        </div>
      </div>

      {/* 정산 금액 섹션 - PAID, BROKER_ACCEPTED, RESERVATION_PAID 상태에서만 표시 */}
      {(currentOrder.status === 'PAID' || 
        currentOrder.status === 'BROKER_ACCEPTED' || 
        currentOrder.status === 'RESERVATION_PAID') && (
        <SettlementPriceEditor 
          order={currentOrder}
          onUpdate={handleSettlementPriceUpdate}
        />
      )}

      {/* 관리자 메모 섹션 - 항상 표시 */}
      <OrderMemoEditor 
        order={currentOrder}
        onUpdate={handleMemoUpdate}
      />

      {/* 메일 템플릿 (결제완료일 때만) */}
      {(currentOrder.status === 'PAID' || currentOrder.status === 'RESERVATION_PAID' || currentOrder.status === 'BROKER_ACCEPTED') && (
        <EmailTemplate order={currentOrder} orderType={orderType} />
      )}

      {/* Stay 검색 모달 */}
      <StaySearchModal
        isOpen={isStaySearchModalOpen}
        onClose={() => setIsStaySearchModalOpen(false)}
        orderId={currentOrder.orderId}
        address={currentOrder.stayName || currentOrder.deliveryAddress || ''}
      />
    </div>
  );
};

export default OrderCard; 