import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Announcement } from '../types';
import { getAnnouncementDetail, deleteAnnouncement } from '../utils/announcementApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import MarkdownViewer from '../components/MarkdownViewer';
import AnnouncementDeleteConfirmModal from '../components/AnnouncementDeleteConfirmModal';

const AnnouncementDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [announcement, setAnnouncement] = useState<Announcement | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // 공지사항 상세 조회
  useEffect(() => {
    if (!id) {
      setError('공지사항 ID가 없습니다.');
      setLoading(false);
      return;
    }

    const fetchAnnouncement = async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await getAnnouncementDetail(id);
        if (response.success) {
          setAnnouncement(response.data);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : '공지사항을 불러오는데 실패했습니다.');
      } finally {
        setLoading(false);
      }
    };

    fetchAnnouncement();
  }, [id]);

  // 삭제 모달 열기
  const handleOpenDeleteModal = () => {
    setDeleteModalOpen(true);
  };

  // 삭제 모달 닫기
  const handleCloseDeleteModal = () => {
    setDeleteModalOpen(false);
  };

  // 공지사항 삭제
  const handleDeleteAnnouncement = async () => {
    if (!id || !announcement) return;

    try {
      setIsDeleting(true);
      const response = await deleteAnnouncement(id);
      if (response.success) {
        showToast('공지사항이 성공적으로 삭제되었습니다.', 'success');
        navigate('/announcements');
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '공지사항 삭제에 실패했습니다.',
        'error'
      );
    } finally {
      setIsDeleting(false);
      setDeleteModalOpen(false);
    }
  };

  // 날짜 포맷팅
  const formatDate = (dateString: string): string => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('ko-KR', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return dateString;
    }
  };

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto">
        <LoadingSpinner />
      </div>
    );
  }

  if (error || !announcement) {
    return (
      <div className="max-w-7xl mx-auto">
        <ErrorMessage
          message={error || '공지사항을 찾을 수 없습니다.'}
          onRetry={() => navigate('/announcements')}
        />
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto">
      {/* 헤더 */}
      <div className="mb-6 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/announcements')}
            className="text-gray-600 hover:text-gray-900 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <div className="flex items-center gap-3">
            {announcement.isPinned && (
              <span className="inline-flex items-center px-2 py-1 rounded text-xs font-medium bg-yellow-100 text-yellow-800">
                고정
              </span>
            )}
            <h1 className="text-2xl font-bold text-gray-900">{announcement.title}</h1>
          </div>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => navigate(`/announcements/${id}/edit`)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            수정
          </button>
          <button
            onClick={handleOpenDeleteModal}
            className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            삭제
          </button>
        </div>
      </div>

      {/* 메타 정보 */}
      <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
        <div className="flex items-center gap-4 text-sm text-gray-500">
          <span>조회수: {announcement.viewCount}</span>
          <span>작성일: {formatDate(announcement.createdDate)}</span>
          {announcement.updatedDate !== announcement.createdDate && (
            <span>수정일: {formatDate(announcement.updatedDate)}</span>
          )}
        </div>
      </div>

      {/* 본문 */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <MarkdownViewer content={announcement.content} />
      </div>

      {/* 삭제 확인 모달 */}
      <AnnouncementDeleteConfirmModal
        isOpen={deleteModalOpen}
        title={announcement.title}
        onConfirm={handleDeleteAnnouncement}
        onCancel={handleCloseDeleteModal}
        isProcessing={isDeleting}
      />
    </div>
  );
};

export default AnnouncementDetailPage;
