// 호스트 퍼널 관련 유틸리티 함수
import { HostSummary, HostFunnelData, HostStage, GateInfo } from '../types';

// 날짜 문자열을 Date 객체로 변환 (날짜만 있는 경우와 시간까지 있는 경우 모두 처리)
const parseDate = (dateString: string): Date => {
  // 시간 정보가 포함된 경우 (예: "2025-01-16T18:30:00")
  if (dateString.includes('T')) {
    return new Date(dateString);
  }
  // 날짜만 있는 경우 (예: "2025-01-16")
  return new Date(dateString + 'T00:00:00');
};

// 두 날짜 사이의 경과 일수 계산
const calculateDaysDifference = (fromDate: string, toDate: Date = new Date()): number => {
  const from = parseDate(fromDate);
  const diffTime = toDate.getTime() - from.getTime();
  return Math.floor(diffTime / (1000 * 60 * 60 * 24));
};

// 게이트 정보 결정 로직
const determineGateInfo = (
  daysSinceInstallation: number | null,
  daysSinceLastAccess: number,
  daysSinceLastOrder: number | null,
  hasInstallation: boolean,
  hasAccess: boolean,
  hasOrder: boolean
): GateInfo => {
  // 설치일이 없는 경우
  if (!hasInstallation) {
    return {
      gate: null,
      action: "",
      status: ""
    };
  }

  // 접속이 없는 경우 (설치 → 접속 단계)
  if (!hasAccess) {
    if (daysSinceInstallation! >= 10) {
      return {
        gate: "Gate2",
        action: "QR 상태 점검 요청 (분실 여부/위치 사전 확인, 필요 시 재발송)",
        status: ""
      };
    } else if (daysSinceInstallation! >= 5) {
      return {
        gate: "Gate1",
        action: "게스트 안내 요청 (호스트에게 안내 협조 요청)",
        status: ""
      };
    }
    // 설치 후 5일 미만이면 대기
    return {
      gate: null,
      action: "대기",
      status: "설치 → 접속"
    };
  }

  // 접속은 있지만 주문이 없는 경우 (접속 → 첫 주문 단계)
  if (!hasOrder) {
    if (daysSinceLastAccess >= 10) {
      return {
        gate: "Gate4",
        action: "최종 리마인드 (게스트 프로모션 재안내 + QR 위치 재점검 + 안내 협조 요청)",
        status: ""
      };
    } else if (daysSinceLastAccess >= 5) {
      return {
        gate: "Gate3",
        action: "게스트 유도용 소액쿠폰 제공 + 호스트 안내 요청",
        status: ""
      };
    }
    // 접속 후 5일 미만이면 대기
    return {
      gate: null,
      action: "대기",
      status: "접속 → 첫 주문"
    };
  }

  // 주문은 있지만 20일 이상 지난 경우 (점검 요망)
  if (daysSinceLastOrder! >= 20) {
    return {
      gate: "Gate5",
      action: "점검 요망 전환: 상태 확인 & 재활성화 제안",
        status: ""
    };
  }

  // 최근 20일 이내 주문이 있는 경우
  return {
    gate: null,
    action: "활성 상태 유지",
    status: ""
  };
};

// 호스트 상태 결정 로직
const determineHostStage = (
  daysSinceInstallation: number | null,
  daysSinceLastAccess: number,
  daysSinceLastOrder: number | null,
  hasInstallation: boolean,
  hasAccess: boolean,
  hasOrder: boolean
): HostStage => {
  // 설치일이 없는 경우
  if (!hasInstallation) {
    return "";
  }

  // 접속이 없는 경우
  if (!hasAccess) {
    return "설치 → 접속";
  }

  // 주문이 없는 경우
  if (!hasOrder) {
    return "접속 → 첫 주문";
  }

  // 주문이 있는 경우
  if (daysSinceLastOrder! < 20) {
    return "활성화";
  } else {
    // 20일 이상 지난 경우 - 추후 예약 확인 기능으로 "보류" 상태 결정 예정
    return "점검 요망 (20일 초과)";
  }
};

// 호스트 요약 데이터를 퍼널 데이터로 변환
export const transformToHostFunnelData = (hostSummary: HostSummary): HostFunnelData => {
  const now = new Date();
  
  // 각 날짜의 존재 여부 확인
  const hasInstallation = hostSummary.installationDate !== null;
  // 접속일이 없어도 주문일이 있으면 접속이 있다고 간주
  const hasAccess = hostSummary.lastAccessDate !== null || hostSummary.lastOrderDate !== null;
  const hasOrder = hostSummary.lastOrderDate !== null;

  // 경과 일수 계산
  const daysSinceInstallation = hasInstallation 
    ? calculateDaysDifference(hostSummary.installationDate!, now)
    : null;
  
  // 접속일이 없어도 주문일이 있으면 주문일을 접속일로 사용
  const daysSinceLastAccess = hostSummary.lastAccessDate !== null
    ? calculateDaysDifference(hostSummary.lastAccessDate!, now)
    : (hostSummary.lastOrderDate !== null
      ? calculateDaysDifference(hostSummary.lastOrderDate!, now)
      : (hasInstallation ? calculateDaysDifference(hostSummary.installationDate!, now) : 0));
  
  const daysSinceLastOrder = hasOrder 
    ? calculateDaysDifference(hostSummary.lastOrderDate!, now)
    : null;

  // 게이트 정보 결정
  const gateInfo = determineGateInfo(
    daysSinceInstallation,
    daysSinceLastAccess,
    daysSinceLastOrder,
    hasInstallation,
    hasAccess,
    hasOrder
  );

  // 상태 결정
  const stage = determineHostStage(
    daysSinceInstallation,
    daysSinceLastAccess,
    daysSinceLastOrder,
    hasInstallation,
    hasAccess,
    hasOrder
  );

  return {
    ...hostSummary,
    // 접속일이 없고 주문일이 있으면 주문일을 접속일로 표시
    lastAccessDate: hostSummary.lastAccessDate || hostSummary.lastOrderDate,
    stage,
    gateInfo,
    daysSinceInstallation,
    daysSinceLastAccess,
    daysSinceLastOrder
  };
};

// 호스트 요약 데이터 배열을 퍼널 데이터 배열로 변환
export const transformHostSummaryList = (hostSummaryList: HostSummary[]): HostFunnelData[] => {
  return hostSummaryList.map(transformToHostFunnelData);
};

// 날짜 포맷팅 (YYYY.MM.DD 형식)
export const formatDateShort = (dateString: string | null): string => {
  if (!dateString) return "-";
  
  const date = parseDate(dateString);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  
  return `${year}.${month}.${day}`;
};

// 상태별 색상 클래스 반환
export const getStageColorClass = (stage: HostStage): string => {
  switch (stage) {
    case "설치 → 접속":
      return "text-blue-600 bg-blue-100";
    case "접속 → 첫 주문":
      return "text-yellow-600 bg-yellow-100";
    case "활성화":
      return "text-green-600 bg-green-100";
    case "점검 요망 (20일 초과)":
      return "text-red-600 bg-red-100";
    default:
      return "text-gray-400 bg-gray-50";
  }
};

// 게이트별 색상 클래스 반환
export const getGateColorClass = (gate: string | null): string => {
  if (!gate) return "text-gray-400";
  
  switch (gate) {
    case "Gate1":
    case "Gate2":
      return "text-blue-600";
    case "Gate3":
    case "Gate4":
      return "text-yellow-600";
    case "Gate5":
      return "text-red-600";
    default:
      return "text-gray-400";
  }
};
