import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Settlement, SettlementSortField } from '../types';
import { getSettlements, settleOrder, unsettleOrder } from '../utils/settlementApi';
import { formatSettlementPrice, calculateTotalSettlement, getDisplayValue } from '../utils/settlementUtils';
import { getCurrentMonthKey, getUniqueMonths, isInMonth, formatMonthLabel, formatFullDate } from '../utils/dateUtils';
import { updateSettlementPrice, updateOrderMemo } from '../utils/orderUpdateApi';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import { useToast } from '../hooks/useToast';

type SortDirection = 'asc' | 'desc';

const SettlementPage: React.FC = () => {
  const [settlements, setSettlements] = useState<Settlement[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [monthFilter, setMonthFilter] = useState<string>(getCurrentMonthKey());
  const [sortField, setSortField] = useState<SettlementSortField>('orderDate');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');
  
  // 편집 상태
  const [editingCell, setEditingCell] = useState<{ orderId: string; field: 'orderPrice' | 'memo' } | null>(null);
  const [editValue, setEditValue] = useState<string>('');
  const [isUpdating, setIsUpdating] = useState(false);
  
  const { showToast } = useToast();

  // API 호출
  const fetchSettlements = useCallback(async (showLoading = true) => {
    try {
      if (showLoading) {
        setLoading(true);
      }
      setError(null);
      
      const response = await getSettlements();
      console.log('정산 데이터 조회 결과:', response.settlements);
      setSettlements(response.settlements);
    } catch (err) {
      setError(err instanceof Error ? err.message : '정산 내역을 불러오는데 실패했습니다.');
    } finally {
      if (showLoading) {
        setLoading(false);
      }
    }
  }, []);

  useEffect(() => {
    fetchSettlements();
  }, [fetchSettlements]);

  // 사용 가능한 월 목록
  const availableMonths = useMemo(() => {
    const dates = settlements.map(s => s.orderDate);
    return getUniqueMonths(dates);
  }, [settlements]);

  // 필터링 및 정렬된 데이터
  const filteredData = useMemo(() => {
    let filtered = settlements;

    // 1. 월별 필터
    if (monthFilter !== '전체') {
      filtered = filtered.filter(s => isInMonth(s.orderDate, monthFilter));
    }

    // 2. 검색 필터 (주문ID, 숙소명, 가맹점명, 호스트명)
    if (searchTerm) {
      const term = searchTerm.toLowerCase().trim();
      filtered = filtered.filter(s =>
        s.orderId.toLowerCase().includes(term) ||
        s.stayName.toLowerCase().includes(term) ||
        s.franchiseStoreName.toLowerCase().includes(term) ||
        (s.hostName && s.hostName.toLowerCase().includes(term))
      );
    }

    // 3. 정렬
    filtered.sort((a, b) => {
      let aValue: any = a[sortField];
      let bValue: any = b[sortField];

      // orderPrice, settlementPrice의 경우 null을 0으로 처리
      if (sortField === 'orderPrice' || sortField === 'settlementPrice') {
        aValue = aValue ?? 0;
        bValue = bValue ?? 0;
      }

      // null 값 처리
      if (aValue === null && bValue === null) return 0;
      if (aValue === null) return sortDirection === 'asc' ? 1 : -1;
      if (bValue === null) return sortDirection === 'asc' ? -1 : 1;

      // 문자열 비교
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }

      // 숫자 비교
      if (aValue < bValue) return sortDirection === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });

    return filtered;
  }, [settlements, monthFilter, searchTerm, sortField, sortDirection]);

  // 통계
  const statistics = useMemo(() => {
    const settledItems = filteredData.filter(s => s.settled);
    const unsettledItems = filteredData.filter(s => !s.settled);
    
    return {
      totalCount: filteredData.length,
      totalAmount: calculateTotalSettlement(filteredData),
      settledCount: settledItems.length,
      settledAmount: calculateTotalSettlement(settledItems),
      unsettledCount: unsettledItems.length,
      unsettledAmount: calculateTotalSettlement(unsettledItems)
    };
  }, [filteredData]);

  // 정렬 핸들러
  const handleSort = (field: SettlementSortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('desc');
    }
  };

  // 정렬 아이콘 렌더링
  const renderSortIcon = (field: SettlementSortField) => {
    if (sortField !== field) {
      return <span className="text-gray-400 ml-1">↕</span>;
    }
    return (
      <span className="text-blue-600 ml-1">
        {sortDirection === 'asc' ? '↑' : '↓'}
      </span>
    );
  };

  // 재시도 핸들러
  const handleRetry = () => {
    fetchSettlements();
  };

  // 편집 시작
  const handleStartEdit = (orderId: string, field: 'orderPrice' | 'memo', currentValue: number | string | null) => {
    setEditingCell({ orderId, field });
    if (field === 'orderPrice') {
      setEditValue(currentValue ? String(currentValue) : '0');
    } else {
      setEditValue(currentValue ? String(currentValue) : '');
    }
  };

  // 편집 취소
  const handleCancelEdit = () => {
    setEditingCell(null);
    setEditValue('');
  };

  // 원주문금액(실제 결제금액) 저장
  const handleSaveOrderPrice = async (orderId: string) => {
    const parsedValue = parseInt(editValue.replace(/,/g, ''));
    
    if (isNaN(parsedValue) || parsedValue < 0) {
      showToast('올바른 금액을 입력해주세요', 'error');
      return;
    }

    setIsUpdating(true);
    try {
      // settlementPrice API가 실제로는 orderPrice(실제 결제금액)를 수정함
      await updateSettlementPrice(orderId, parsedValue);
      
      showToast('원주문금액이 수정되었습니다', 'success');
      setEditingCell(null);
      setEditValue('');
      
      // 전체 데이터 새로고침 (로딩 스피너 없이)
      await fetchSettlements(false);
    } catch (err) {
      showToast(err instanceof Error ? err.message : '저장에 실패했습니다', 'error');
    } finally {
      setIsUpdating(false);
    }
  };

  // 메모 저장
  const handleSaveMemo = async (orderId: string) => {
    const trimmedMemo = editValue.trim();
    const memoValue = trimmedMemo === '' ? null : trimmedMemo;

    setIsUpdating(true);
    try {
      await updateOrderMemo(orderId, memoValue);
      
      showToast('메모가 수정되었습니다', 'success');
      setEditingCell(null);
      setEditValue('');
      
      // 전체 데이터 새로고침 (로딩 스피너 없이)
      await fetchSettlements(false);
    } catch (err) {
      showToast(err instanceof Error ? err.message : '저장에 실패했습니다', 'error');
    } finally {
      setIsUpdating(false);
    }
  };

  // 엔터키 처리
  const handleKeyDown = (e: React.KeyboardEvent, orderId: string, field: 'orderPrice' | 'memo') => {
    if (e.key === 'Enter') {
      if (field === 'orderPrice') {
        handleSaveOrderPrice(orderId);
      } else {
        handleSaveMemo(orderId);
      }
    } else if (e.key === 'Escape') {
      handleCancelEdit();
    }
  };

  // 정산 완료 처리
  const handleSettle = async (orderId: string) => {
    if (!window.confirm('정산을 완료하시겠습니까?')) {
      return;
    }

    try {
      await settleOrder(orderId);
      showToast('정산이 완료되었습니다', 'success');
      await fetchSettlements(false);
    } catch (err) {
      showToast(err instanceof Error ? err.message : '정산 처리에 실패했습니다', 'error');
    }
  };

  // 정산 취소 처리
  const handleUnsettle = async (orderId: string) => {
    if (!window.confirm('정산을 취소하시겠습니까?')) {
      return;
    }

    try {
      await unsettleOrder(orderId);
      showToast('정산이 취소되었습니다', 'success');
      await fetchSettlements(false);
    } catch (err) {
      showToast(err instanceof Error ? err.message : '정산 취소에 실패했습니다', 'error');
    }
  };

  return (
    <>
      {loading && <LoadingSpinner />}
      
      {error && (
        <ErrorMessage 
          message={error} 
          onRetry={handleRetry}
        />
      )}
      
      {!loading && !error && (
        <div className="w-full space-y-6">
          {/* 페이지 헤더 */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h1 className="text-2xl font-bold text-gray-900 mb-4">정산 목록</h1>
            
            {/* 통계 카드 */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
              <div className="text-center p-4 bg-gray-50 rounded-lg">
                <div className="text-3xl font-bold text-gray-900">{statistics.totalCount}건</div>
                <div className="text-sm text-gray-600 mt-1">총 건수</div>
              </div>
              <div className="text-center p-4 bg-blue-50 rounded-lg">
                <div className="text-3xl font-bold text-blue-600">
                  {statistics.totalAmount.toLocaleString()}원
                </div>
                <div className="text-sm text-gray-600 mt-1">총 리워드 금액</div>
              </div>
              <div className="text-center p-4 bg-green-50 rounded-lg">
                <div className="text-3xl font-bold text-green-600">{statistics.settledCount}건</div>
                <div className="text-lg font-semibold text-green-700 mt-1">
                  {statistics.settledAmount.toLocaleString()}원
                </div>
                <div className="text-sm text-gray-600 mt-1">정산 완료</div>
              </div>
              <div className="text-center p-4 bg-orange-50 rounded-lg">
                <div className="text-3xl font-bold text-orange-600">{statistics.unsettledCount}건</div>
                <div className="text-lg font-semibold text-orange-700 mt-1">
                  {statistics.unsettledAmount.toLocaleString()}원
                </div>
                <div className="text-sm text-gray-600 mt-1">정산 대기</div>
              </div>
            </div>

            {/* 필터 및 검색 */}
            <div className="flex flex-col md:flex-row gap-4">
              {/* 검색 */}
              <div className="flex-1">
                <input
                  type="text"
                  placeholder="주문ID, 숙소명, 가맹점명, 호스트명 검색..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>
              
              {/* 월별 필터 */}
              <select
                value={monthFilter}
                onChange={(e) => setMonthFilter(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="전체">전체 기간</option>
                {availableMonths.map(month => (
                  <option key={month} value={month}>{formatMonthLabel(month)}</option>
                ))}
              </select>
            </div>
          </div>

          {/* 테이블 */}
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('orderDate')}
                      style={{ width: '105px' }}
                    >
                      주문일 {renderSortIcon('orderDate')}
                    </th>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                      style={{ width: '120px' }}
                    >
                      주문ID
                    </th>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('stayName')}
                    >
                      숙소명 {renderSortIcon('stayName')}
                    </th>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('franchiseStoreName')}
                    >
                      가맹점명 {renderSortIcon('franchiseStoreName')}
                    </th>
                    <th 
                      className="px-3 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('orderPrice')}
                      style={{ width: '100px' }}
                    >
                      원주문금액 {renderSortIcon('orderPrice')}
                    </th>
                    <th 
                      className="px-3 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('settlementPrice')}
                      style={{ width: '100px' }}
                    >
                      리워드 금액 {renderSortIcon('settlementPrice')}
                    </th>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('hostName')}
                      style={{ width: '85px' }}
                    >
                      호스트 {renderSortIcon('hostName')}
                    </th>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                      style={{ width: '110px' }}
                    >
                      연락처
                    </th>
                    <th 
                      className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                      style={{ width: '150px' }}
                    >
                      메모
                    </th>
                    <th 
                      className="px-3 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider"
                      style={{ width: '100px' }}
                    >
                      정산 여부
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {filteredData.map((settlement, index) => (
                    <tr 
                      key={`${settlement.orderId}-${index}`} 
                      className={`${
                        settlement.settled 
                          ? 'bg-green-50 hover:bg-green-100 opacity-75' 
                          : 'hover:bg-gray-50'
                      }`}
                    >
                      <td className={`px-3 py-3 whitespace-nowrap text-xs ${settlement.settled ? 'text-gray-500' : 'text-gray-900'}`}>
                        {formatFullDate(settlement.orderDate)}
                      </td>
                      <td className={`px-3 py-3 text-xs ${settlement.settled ? 'text-gray-500' : 'text-gray-900'} font-mono`}>
                        <div className="truncate" title={settlement.orderId}>
                          {settlement.orderId}
                        </div>
                      </td>
                      <td className={`px-3 py-3 text-xs ${settlement.settled ? 'text-gray-500' : 'text-gray-900'}`}>
                        <div className="line-clamp-2" title={settlement.stayName}>
                          {settlement.stayName}
                        </div>
                      </td>
                      <td className={`px-3 py-3 text-xs ${settlement.settled ? 'text-gray-500' : 'text-gray-900'}`}>
                        <div className="line-clamp-2" title={settlement.franchiseStoreName}>
                          {settlement.franchiseStoreName}
                        </div>
                      </td>
                      <td className="px-3 py-3 whitespace-nowrap text-xs text-right">
                        {editingCell?.orderId === settlement.orderId && editingCell?.field === 'orderPrice' ? (
                          <div className="flex items-center gap-1">
                            <input
                              type="text"
                              value={editValue}
                              onChange={(e) => {
                                const value = e.target.value.replace(/,/g, '');
                                if (value === '' || /^\d+$/.test(value)) {
                                  setEditValue(value ? parseInt(value).toLocaleString() : '');
                                }
                              }}
                              onKeyDown={(e) => handleKeyDown(e, settlement.orderId, 'orderPrice')}
                              disabled={isUpdating}
                              className="w-20 px-2 py-1 border border-blue-500 rounded text-xs text-right focus:outline-none focus:ring-1 focus:ring-blue-500"
                              autoFocus
                            />
                            <button
                              onClick={() => handleSaveOrderPrice(settlement.orderId)}
                              disabled={isUpdating}
                              className="text-green-600 hover:text-green-700 disabled:opacity-50"
                              title="저장"
                            >
                              ✓
                            </button>
                            <button
                              onClick={handleCancelEdit}
                              disabled={isUpdating}
                              className="text-red-600 hover:text-red-700 disabled:opacity-50"
                              title="취소"
                            >
                              ✕
                            </button>
                          </div>
                        ) : (
                          <button
                            onClick={() => handleStartEdit(settlement.orderId, 'orderPrice', settlement.orderPrice)}
                            className={`${settlement.settled ? 'text-gray-500' : 'text-gray-900'} hover:text-blue-600 hover:underline w-full text-right`}
                          >
                            {formatSettlementPrice(settlement.orderPrice)}
                          </button>
                        )}
                      </td>
                      <td className={`px-3 py-3 whitespace-nowrap text-xs ${settlement.settled ? 'text-gray-500' : 'text-gray-900'} text-right font-semibold`}>
                        {formatSettlementPrice(settlement.settlementPrice)}
                      </td>
                      <td className={`px-3 py-3 whitespace-nowrap text-xs ${settlement.settled ? 'text-gray-500' : 'text-gray-900'}`}>
                        {getDisplayValue(settlement.hostName)}
                      </td>
                      <td className={`px-3 py-3 whitespace-nowrap text-xs ${settlement.settled ? 'text-gray-400' : 'text-gray-500'}`}>
                        {getDisplayValue(settlement.hostContact)}
                      </td>
                      <td className="px-3 py-3 text-xs">
                        {editingCell?.orderId === settlement.orderId && editingCell?.field === 'memo' ? (
                          <div className="flex items-center gap-1">
                            <input
                              type="text"
                              value={editValue}
                              onChange={(e) => setEditValue(e.target.value)}
                              onKeyDown={(e) => handleKeyDown(e, settlement.orderId, 'memo')}
                              disabled={isUpdating}
                              className="flex-1 px-2 py-1 border border-blue-500 rounded text-xs focus:outline-none focus:ring-1 focus:ring-blue-500"
                              autoFocus
                              placeholder="메모 입력"
                            />
                            <button
                              onClick={() => handleSaveMemo(settlement.orderId)}
                              disabled={isUpdating}
                              className="text-green-600 hover:text-green-700 disabled:opacity-50"
                              title="저장"
                            >
                              ✓
                            </button>
                            <button
                              onClick={handleCancelEdit}
                              disabled={isUpdating}
                              className="text-red-600 hover:text-red-700 disabled:opacity-50"
                              title="취소"
                            >
                              ✕
                            </button>
                          </div>
                        ) : (
                          <button
                            onClick={() => handleStartEdit(settlement.orderId, 'memo', settlement.memo)}
                            className={`${settlement.settled ? 'text-gray-400' : 'text-gray-500'} hover:text-blue-600 hover:underline w-full text-left`}
                          >
                            <div className="line-clamp-2" title={settlement.memo || ''}>
                              {getDisplayValue(settlement.memo)}
                            </div>
                          </button>
                        )}
                      </td>
                      <td className="px-3 py-3 text-center">
                        {settlement.settled ? (
                          <div className="flex flex-col items-center gap-1">
                            <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                              완료
                            </span>
                            <button
                              onClick={() => handleUnsettle(settlement.orderId)}
                              className="text-xs text-red-600 hover:text-red-700 hover:underline"
                            >
                              취소
                            </button>
                          </div>
                        ) : (
                          <button
                            onClick={() => handleSettle(settlement.orderId)}
                            className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-gray-100 text-gray-800 hover:bg-blue-100 hover:text-blue-800"
                          >
                            완료 처리
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* 데이터가 없는 경우 */}
            {filteredData.length === 0 && (
              <div className="text-center py-16">
                <svg 
                  className="mx-auto h-12 w-12 text-gray-400" 
                  fill="none" 
                  viewBox="0 0 24 24" 
                  stroke="currentColor"
                >
                  <path 
                    strokeLinecap="round" 
                    strokeLinejoin="round" 
                    strokeWidth={2} 
                    d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" 
                  />
                </svg>
                <p className="mt-4 text-lg text-gray-600">
                  {searchTerm || monthFilter !== getCurrentMonthKey()
                    ? '검색 조건에 맞는 정산 내역이 없습니다.'
                    : '이번 달 정산 내역이 없습니다.'}
                </p>
                {searchTerm && (
                  <button 
                    onClick={() => setSearchTerm('')}
                    className="mt-4 text-blue-600 hover:text-blue-700 font-medium"
                  >
                    검색 초기화
                  </button>
                )}
              </div>
            )}
          </div>

          {/* 결과 요약 */}
          {filteredData.length > 0 && (
            <div className="bg-white rounded-lg shadow-sm p-4">
              <p className="text-sm text-gray-600">
                총 {settlements.length}개 중 {filteredData.length}개 표시
                {searchTerm && ` (검색: "${searchTerm}")`}
                {monthFilter !== '전체' && ` (필터: ${formatMonthLabel(monthFilter)})`}
              </p>
            </div>
          )}
        </div>
      )}
    </>
  );
};

export default SettlementPage;

