// 메뉴얼 API 함수
import {
  ManualListApiResponse,
  ManualDetailApiResponse,
  ManualVersionsApiResponse,
  ManualCreateApiResponse,
  ManualUpdateApiResponse,
  ManualVersionUpdateApiResponse,
  ManualCategoryChangeApiResponse,
  ManualReorderApiResponse,
  ManualDeleteApiResponse,
  ManualFilterParams,
  CreateManualRequest,
  UpdateManualRequest,
  UpdateManualVersionRequest,
  ReorderManualRequest,
  ChangeManualCategoryRequest,
} from '../types';

// 환경에 따른 API URL 설정
const getApiBaseUrl = () => {
  // 개발 환경
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  
  // 운영 환경 - 기본값으로 운영 API 서버 사용
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

// 공통 헤더 (인증 불필요한 조회는 헤더 없이, 생성/수정/삭제는 인증 필요)
const getHeaders = (requireAuth: boolean = false) => {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
  };
  
  if (requireAuth) {
    headers['X-SERVER-AUTH'] = 'secret';
  }
  
  return headers;
};

// 공통 에러 처리
const handleResponseError = async (response: Response) => {
  if (response.status === 400) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.message || '잘못된 요청입니다.');
  } else if (response.status === 401 || response.status === 403) {
    throw new Error('인증이 필요합니다.');
  } else if (response.status === 404) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.message || '요청한 리소스를 찾을 수 없습니다.');
  } else if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  } else {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
};

// 네트워크 에러 처리
const handleNetworkError = (error: unknown) => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }
  throw error;
};

// 메뉴얼 목록 조회
export const getManualList = async (
  params: ManualFilterParams = {}
): Promise<ManualListApiResponse> => {
  const searchParams = new URLSearchParams();
  
  if (params.page !== undefined) searchParams.append('page', String(params.page));
  if (params.size !== undefined) searchParams.append('size', String(params.size));
  if (params.keyword) searchParams.append('keyword', params.keyword);
  if (params.categoryId) searchParams.append('categoryId', params.categoryId);
  if (params.startDate) searchParams.append('startDate', params.startDate);
  if (params.endDate) searchParams.append('endDate', params.endDate);
  
  const queryString = searchParams.toString();
  const url = `${API_BASE_URL}/api/manuals${queryString ? `?${queryString}` : ''}`;
  
  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: getHeaders(false), // 목록 조회는 인증 불필요
      mode: 'cors',
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

