import React, { useState } from 'react';
import { HostStay } from '../types';
import { updateStayNote } from '../utils/hostApi';
import { useToast } from '../hooks/useToast';
import StayQRCodeModal from './StayQRCodeModal';

interface StayListProps {
  stays: HostStay[];
  onUpdate?: () => void;
}

const StayList: React.FC<StayListProps> = ({ stays, onUpdate }) => {
  const [selectedStay, setSelectedStay] = useState<HostStay | null>(null);
  const [qrModalOpen, setQrModalOpen] = useState(false);
  const [editingStayId, setEditingStayId] = useState<string | null>(null);
  const [editingNote, setEditingNote] = useState<string>('');
  const [isSaving, setIsSaving] = useState(false);
  const { showToast } = useToast();

  const handleQRCodeClick = (stay: HostStay) => {
    setSelectedStay(stay);
    setQrModalOpen(true);
  };

  const handleQRModalClose = () => {
    setQrModalOpen(false);
    setSelectedStay(null);
  };

  const handleEditClick = (stay: HostStay) => {
    setEditingStayId(stay.id);
    setEditingNote(stay.note || '');
  };

  const handleCancelEdit = () => {
    setEditingStayId(null);
    setEditingNote('');
  };

  const handleSaveNote = async (stay: HostStay) => {
    setIsSaving(true);
    try {
      const noteToSave = editingNote.trim() || null;
      await updateStayNote(stay.stayId, noteToSave);
      showToast('메모가 저장되었습니다.', 'success');
      setEditingStayId(null);
      setEditingNote('');
      onUpdate?.();
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '메모 저장에 실패했습니다.',
        'error'
      );
    } finally {
      setIsSaving(false);
    }
  };

  if (stays.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        연결된 Stay가 없습니다.
      </div>
    );
  }

  return (
    <>
      <div className="max-h-96 overflow-y-auto space-y-3">
        {stays.map((stay) => (
          <div
            key={stay.id}
            className="bg-gray-50 rounded-lg p-4 border border-gray-200"
          >
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <h4 className="font-semibold text-gray-900 mb-2">{stay.stayName}</h4>
                <div className="space-y-1 text-sm text-gray-600">
                  <p>
                    <span className="font-medium">Stay ID:</span> {stay.stayId}
                  </p>
                  {stay.installationDate && (
                    <p>
                      <span className="font-medium">설치일:</span> {stay.installationDate}
                    </p>
                  )}
                  {/* 메모 영역 - 편집 모드 */}
                  <div className="mt-2">
                    <span className="font-medium">메모:</span>
                    {editingStayId === stay.id ? (
                      <div className="mt-1">
                        <textarea
                          value={editingNote}
                          onChange={(e) => setEditingNote(e.target.value)}
                          className="w-full px-3 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none"
                          rows={3}
                          placeholder="메모를 입력하세요"
                          disabled={isSaving}
                        />
                        <div className="flex gap-2 mt-2">
                          <button
                            onClick={() => handleSaveNote(stay)}
                            disabled={isSaving}
                            className="px-3 py-1 text-xs bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors disabled:opacity-50"
                          >
                            {isSaving ? '저장 중...' : '저장'}
                          </button>
                          <button
                            onClick={handleCancelEdit}
                            disabled={isSaving}
                            className="px-3 py-1 text-xs bg-gray-200 text-gray-700 rounded hover:bg-gray-300 transition-colors disabled:opacity-50"
                          >
                            취소
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="flex items-start gap-2 mt-1">
                        <span className="flex-1 text-gray-600 whitespace-pre-wrap">
                          {stay.note || <span className="text-gray-400 italic">메모 없음</span>}
                        </span>
                        <button
                          onClick={() => handleEditClick(stay)}
                          className="p-1 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded transition-colors flex-shrink-0"
                          title="메모 수정"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                          </svg>
                        </button>
                      </div>
                    )}
                  </div>
                  {stay.displayInfo && (
                    <p>
                      <span className="font-medium">표시 정보:</span> {stay.displayInfo}
                    </p>
                  )}
                </div>
              </div>
              {/* QR 코드 버튼 */}
              <button
                onClick={() => handleQRCodeClick(stay)}
                className="ml-3 p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                title="QR 코드 생성"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h2M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
                </svg>
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* QR 코드 모달 */}
      {selectedStay && (
        <StayQRCodeModal
          isOpen={qrModalOpen}
          stay={selectedStay}
          onClose={handleQRModalClose}
        />
      )}
    </>
  );
};

export default StayList;

